# Generated by the start-bridge codemod for playground; re-run it instead of editing.
"""Validate and preserve the playground staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import os
from pathlib import Path

PROFILE = os.environ.get("VITE_PLAYGROUND_NATIVE_PROFILE", "staging")
if PROFILE not in ("staging", "production"):
    raise ValueError("Unknown playground native profile")
WORKER = "tuturuuu-playground" if PROFILE == "production" else "tuturuuu-playground-vite-staging"
PUBLIC_FILES = (
    "file.svg",
    "globe.svg",
    "next.svg",
    "robots.txt",
    "vercel.svg",
    "window.svg",
)


def load():
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("playground_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": WORKER,
        "vars": {"TUTURUUU_NOINDEX": "0" if PROFILE == "production" else "1"},
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": WORKER}
    module.RECEIPT = "playground-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "PLAYGROUND_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["PLAYGROUND_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load().main()


if __name__ == "__main__":
    main()
